INSERT OR IGNORE INTO `exercises` (`id`,`name`,`equipment`,`kind`,`is_custom`,`is_favorite`,`bar_weight_kg`,`default_rest_sec`,`track_rpe`,`description`,`cues`,`created_at`,`updated_at`) VALUES
('reverse-crunch','Reverse Crunch','bodyweight','isolation',0,0,NULL,90,0,'Lie flat on your back with your arms extended along your sides. Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor. Contract your abs and curl your hips off the floor, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.','["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('russian-twist','Russian Twist','bodyweight','compound',0,0,NULL,180,0,'Sit on the ground with your knees bent and feet flat on the floor. Lean back slightly while keeping your back straight and your core engaged. Hold your hands together in front of your chest or hold a weight if desired. Lift your feet off the ground, balancing on your sit bones. Twist your torso to the right, bringing your hands or weight towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body. Continue alternating sides for the desired number of repetitions.','["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]',1788745400000,1788745400000),
('bicycle-crunch','Bicycle Crunch','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('mountain-climber','Mountain Climber','bodyweight','isolation',0,0,NULL,90,0,'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest. Continue alternating legs in a running motion, keeping your hips low and your core engaged. Maintain a steady pace and breathe evenly throughout the exercise. Repeat for the desired number of repetitions.','["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('dead-bug','Dead Bug','bodyweight','compound',0,0,NULL,180,0,'Lie flat on your back with your arms extended towards the ceiling. Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees. Engage your core and lower back to press your lower back into the ground. Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor. Pause for a moment, then return to the starting position. Repeat the movement with your left arm and right leg. Continue alternating sides for the desired number of repetitions.','["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]',1788745400000,1788745400000),
('bird-dog','Bird Dog','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('pallof-press','Pallof Press','cable','isolation',0,0,NULL,90,0,NULL,'["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."]',1788745400000,1788745400000),
('cable-woodchop','Cable Woodchop','cable','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('half-kneeling-pallof-press','Half-Kneeling Pallof Press','cable','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('cable-pallof-hold','Cable Pallof Hold','cable','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('hanging-knee-raise','Hanging Knee Raise','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('captains-chair-knee-raise','Captain''s Chair Knee Raise','machine','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('decline-sit-up','Decline Sit-Up','bodyweight','isolation',0,0,NULL,90,0,'Lie on a decline bench with your feet secured and your knees bent. Place your hands behind your head or across your chest. Engage your abs and lift your upper body off the bench, curling forward towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.','["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('weighted-crunch','Weighted Crunch','other','isolation',0,0,NULL,90,0,'Lie flat on your back with your knees bent and feet flat on the ground. Hold a weight plate or dumbbell on your chest. Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.','["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('weighted-russian-twist','Weighted Russian Twist','dumbbell','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('dumbbell-side-bend','Dumbbell Side Bend','dumbbell','isolation',0,0,NULL,90,0,'Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side. Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can. Pause for a moment, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat.','["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."]',1788745400000,1788745400000),
('elliptical','Elliptical','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('swimming','Swimming','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('jump-rope','Jump Rope','other','isolation',0,0,NULL,90,0,'Hold the handles of the jump rope with your hands, palms facing inward. Stand with your feet shoulder-width apart and knees slightly bent. Swing the rope over your head and jump over it as it comes towards your feet. Land softly on the balls of your feet and repeat the jump as the rope comes around again. Continue jumping for the desired duration or number of repetitions.','["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."]',1788745400000,1788745400000),
('assault-bike','Assault Bike','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('skierg','SkiErg','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('hiking','Hiking','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('treadmill-incline-walk','Treadmill Incline Walk','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('battle-ropes','Battle Ropes','other','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('incline-push-up','Incline Push-up','bodyweight','compound',0,0,NULL,180,0,'Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart. Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels. Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.','["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('knee-push-up','Knee Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('wide-push-up','Wide Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,'["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.","To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."]',1788745400000,1788745400000),
('diamond-push-up','Diamond Push-up','bodyweight','isolation',0,0,NULL,90,0,'Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers. Keep your body in a straight line from head to toe, engaging your core and glutes. Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.','["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('decline-push-up','Decline Push-up','bodyweight','compound',0,0,NULL,180,0,'Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface. Keep your body in a straight line from head to toe, engaging your core muscles. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.','["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('pike-push-up','Pike Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('feet-elevated-pike-push-up','Feet-Elevated Pike Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('archer-push-up','Archer Push-up','bodyweight','compound',0,0,NULL,180,0,'Start in a push-up position with your hands slightly wider than shoulder-width apart. Extend one arm straight out to the side, parallel to the ground. Lower your body by bending your elbows, keeping your back straight and core engaged. Push back up to the starting position. Repeat on the other side, extending the opposite arm out to the side. Continue alternating sides for the desired number of repetitions.','["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."]',1788745400000,1788745400000),
('typewriter-push-up','Typewriter Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('explosive-push-up','Explosive Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('hindu-push-up','Hindu Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('scapular-push-up','Scapular Push-up','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('push-up-shoulder-tap','Push-up Shoulder Tap','bodyweight','isolation',0,0,NULL,90,0,'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you push back up, lift your right hand off the ground and tap your left shoulder. Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder. Continue alternating shoulder taps with each push-up repetition. Maintain a stable core and avoid excessive hip rotation throughout the exercise. Repeat for the desired number of repetitions.','["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."]',1788745400000,1788745400000),
('wall-push-up','Wall Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('wall-walk','Wall Walk','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000),
('wall-handstand-push-up','Wall Handstand Push-up','bodyweight','compound',0,0,NULL,180,0,NULL,NULL,1788745400000,1788745400000);
