('side-plank-hip-dip','Side Plank Hip Dip','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('copenhagen-plank','Copenhagen Plank','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('dragon-flag','Dragon Flag','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000),
('burpee','Burpee','bodyweight','compound',0,0,NULL,180,0,'Start in a standing position with your feet shoulder-width apart. Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you. Kick your feet back into a push-up position. Perform a push-up, keeping your body in a straight line. Jump your feet back into the squat position. Jump up explosively, reaching your arms overhead. Land softly and immediately lower back into a squat position to begin the next repetition.','["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."]',1788745400000,1788745400000),
('half-burpee','Half Burpee','bodyweight','isolation',0,0,NULL,90,0,NULL,NULL,1788745400000,1788745400000);
